import{_ as o,c as r,o as e,aj as a}from"./chunks/framework.B5VMNd4r.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"handbook/user-cognition/prompts/chapter_1_prompt.md","filePath":"handbook/user-cognition/prompts/chapter_1_prompt.md","lastUpdated":1783615807000}'),i={name:"handbook/user-cognition/prompts/chapter_1_prompt.md"};function l(n,t,p,u,s,d){return e(),r("div",null,[...t[0]||(t[0]=[a('<p>根据下面的文章目录，以IP「怕浪猫」的名义写一篇关于&quot;记忆偏差&quot;的文章，图文并茂，正文中用图片占位符说明需要配图的位置和描述，图片使用&quot;<div style="margin:24px 0;padding:24px;background:#f6f6f6;border-radius:8px;text-align:center;color:#888;"><em>图：图片描述</em></div>&quot;格式（URL留空即可），图标尽量不出现。</p><p>IP名称使用规范：</p><ul><li>自我介绍时用&quot;我是怕浪猫&quot;，第一人称可交替使用&quot;我&quot;和&quot;怕浪猫&quot;</li><li>禁止用&quot;小编&quot;自称</li><li>IP名称自然融入，不刻意强调</li></ul><h4 id="第1章-记忆的陷阱——大脑如何偷偷篡改你的过去" tabindex="-1">第1章 记忆的陷阱——大脑如何偷偷篡改你的过去 <a class="header-anchor" href="#第1章-记忆的陷阱——大脑如何偷偷篡改你的过去" aria-label="Permalink to “第1章 记忆的陷阱——大脑如何偷偷篡改你的过去”">​</a></h4><p><strong>章节结构（5节）：</strong></p><ul><li>1.1 我们的大脑，天生就是一个&quot;篡改记忆&quot;的骗子——从基本归因错误和光晕效应说起</li><li>1.2 可得性启发法 + 谷歌效应：越容易想到的事情，越容易被当成真相</li><li>1.3 蔡加尼克效应 + 宜家效应：未完成的事和亲手做的东西，为什么让你念念不忘</li><li>1.4 虚假记忆 + 隐记忆：想象的经历如何悄悄变成&quot;真实记忆&quot;</li><li>1.5 记忆偏差实战指南：如何在生活中识别并对抗记忆陷阱</li></ul><h4 id="互动-收藏-涨粉模块-必须遵循" tabindex="-1">互动/收藏/涨粉模块（必须遵循） <a class="header-anchor" href="#互动-收藏-涨粉模块-必须遵循" aria-label="Permalink to “互动/收藏/涨粉模块（必须遵循）”">​</a></h4><p><strong>开头3秒钩子（必须写）：</strong> 用反常识型或痛点共鸣型开头，例如： &quot;你记忆中三年前的夏天是25度，但实际上那一年夏天平均气温只有22度。大脑不只是存储记忆，它还在不断&#39;编辑&#39;记忆——而这种编辑，往往是在你自己不知情的情况下完成的。&quot;</p><p>开头钩子后紧跟IP自我介绍：&quot;我是怕浪猫，一个专注研究认知科学和决策心理的写作者。过去三年，我拆解了超过100个认知偏差，发现记忆偏差是最容易被忽视、却影响最深的一类。&quot;</p><p><strong>每300字金句（必须包含）：</strong> 在正文中至少嵌入3-4个&quot;截图级金句&quot;——让人想截图/收藏的浓缩表达。 金句格式：用引用块 <code>&gt; xxx</code> 标注</p><p><strong>收藏触发结构（必须包含至少1个）：</strong> 在正文中必须使用以下&quot;高收藏&quot;内容结构：</p><ul><li>清单型：&quot;8个记忆偏差完整清单&quot;</li><li>对比型：&quot;有偏差的判断 vs 理性判断&quot;</li><li>步骤型：&quot;三步识别记忆扭曲&quot;</li></ul><p><strong>结尾CTA（必须写）：</strong> 文章结尾必须包含以下3层CTA：</p><ol><li>收藏引导：&quot;觉得有用？收藏起来，下次直接照抄&quot;</li><li>互动引导：&quot;你有没有过&#39;明明没经历过，却感觉很熟悉&#39;的经历？评论区说说&quot;</li><li>追更引导：&quot;关注怕浪猫，下期我们讲&#39;社交偏差&#39;——为什么你总觉得别人比你更自私？系列进度 1/6&quot;</li></ol><p><strong>下章预告（必须写）：</strong> 在CTA之后，用一段话预告下一章内容，制造期待感。</p><h4 id="_8个偏差详细内容" tabindex="-1">8个偏差详细内容 <a class="header-anchor" href="#_8个偏差详细内容" aria-label="Permalink to “8个偏差详细内容”">​</a></h4><p><strong>1. 基本归因错误（Fundamental Attribution Error）</strong> 解释：用他人的人品和性格来评判他人，却用外部情况来为自己开脱。 案例：你迟到了，说&quot;堵车了&quot;；别人迟到了，你想&quot;他就是不守时的人&quot;。 机制：当观察他人时，关注的是行为本身；当我们自己犯错时，关注的是情境压力。</p><p><strong>2. 光晕效应（Halo Effect）</strong> 解释：如果一个人有某个正面特质，这种正面印象会蔓延到其整体，反之亦然。 案例：长相好看的人被认为更聪明、更有能力；穿着邋遢的人被认为不可靠。 机制：认知经济性——大脑用单一特征推断整体特征，以节省认知资源。</p><p><strong>3. 可得性启发法（Availability Heuristic）</strong> 解释：做决定时，依赖于脑海中直接浮现的例子，而不是真实统计数据。 案例：飞机失事新闻后，大量人取消航班改乘汽车，尽管飞机实际上更安全。 机制：越是生动、情绪化、近期的事件，越容易从记忆中检索，从而被高估其发生概率。</p><p><strong>4. 谷歌效应（Google Effect / Digital Amnesia）</strong> 解释：倾向于遗忘那些容易通过搜索引擎搜索到的信息。 案例：你记不住某个明星的出生年份，因为知道&quot;随时可以搜到&quot;。 机制：外部存储（搜索引擎）减少了大脑编码和存储信息的必要性。</p><p><strong>5. 蔡加尼克效应（Zeigarnik Effect）</strong> 解释：相比于已完成的工作，人们更容易记得未完成的工作。 案例：电影在悬念处结束，你一整晚都在想结局；完结的剧反而没那么牵挂。 机制：未完成的任务会在认知系统中保持&quot;激活状态&quot;，直到被关闭。</p><p><strong>6. 宜家效应（IKEA Effect）</strong> 解释：我们会高估自己参与制作的事物或自己组装的东西的价值。 案例：自己组装的家具觉得特别好，哪怕其实有点歪；自己做的菜觉得格外好吃。 机制：参与创造产生了禀赋效应和能力幻觉——我们喜欢自己亲手创造的东西，并将其价值与自我价值绑定。</p><p><strong>7. 虚假记忆（False Memory）</strong> 解释：我们会错把想象当做真实的记忆。 案例：在引导性提问下，受试者会&quot;记得&quot;从未发生的事件（如童年差点走失）。 机制：记忆不是录像回放，而是重建过程；想象的内容在大脑中产生的神经活动与真实经历高度相似。</p><p><strong>8. 隐记忆（Implicit Memory）</strong> 解释：我们会错把真实的记忆当做想象。 案例：某个场景似曾相识（Céline Dion的&quot;Déjà Vu&quot;体验），实际上是你以前确实经历过但无法有意识地提取。 机制：无意识的记忆提取——记忆存在但有意识地无法访问，被误认为是&quot;凭空想象&quot;。</p><h4 id="图片占位符要求" tabindex="-1">图片占位符要求 <a class="header-anchor" href="#图片占位符要求" aria-label="Permalink to “图片占位符要求”">​</a></h4><p>在每个偏差的解释处，添加一张说明性图片占位符，格式： <code>&lt;div style=&quot;margin: 24px 0; padding: 24px; background: #f6f6f6; border-radius: 8px; text-align: center; color: #888;&quot;&gt;&lt;em&gt;图：偏差名称：简短描述&lt;/em&gt;&lt;/div&gt;</code></p><p>例如： <code>&lt;div style=&quot;margin: 24px 0; padding: 24px; background: #f6f6f6; border-radius: 8px; text-align: center; color: #888;&quot;&gt;&lt;em&gt;图：光晕效应：长相吸引力和能力评价的相关性示意图&lt;/em&gt;&lt;/div&gt;</code></p><p>确保图片描述准确，且正文中有对图片内容的文字说明。</p>',28)])])}const c=o(i,[["render",l]]);export{q as __pageData,c as default};
